448			t.Fatal(err)
449		}
450		// t=100 位姿 (1,0)，K(1,0)；t=200 位姿 (2,0)，K(2,0)；合并后 K(1.5,0) 次数 2。
451		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
452			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
453			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
454		}}); err != nil {
