497		}
498		approxEq(t, "K mean after append", lms[0].X, 5.5/3.0)
499	
500		// 仅覆盖依据完整新范围的校正可成功；旧观测贡献固定不变。
501		rec, err := m2.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 2.0, Y: 0}})
502		if err != nil {
503			t.Fatalf("correct new range: %v", err)
504		}
505		if rec.EndTime != 300 || len(rec.Poses) != 1 {
506			t.Fatalf("record = %+v", rec)
507		}
508		// 新观测从 (2.5,0) 移到 (2.0,0)，与固定旧均值 (1.5,0) 距离 0.5 可接受。
509		lc := rec.Landmarks[0]
510		if lc.ID != "K" {
511			t.Fatalf("change id = %q", lc.ID)
512		}
513		approxEq(t, "K after correct", lc.After.X, (1.5*2+2.0)/3.0)
514		if lc.After.Count != 3 {
515			t.Fatalf("K count = %d", lc.After.Count)
516		}
517	
518		// 新范围校正若让新观测远离固定旧贡献，仍冲突拒绝。
519		_, err = m2.Correct(Correction{ID: "c3", Anchor: 300, Target: CorrectionTarget{X: 10, Y: 0}})
520		r, ok := AsRejectError(err)
521		if !ok || r.Kind != RejectLandmarkConflict || r.Landmark != "K" || r.Time != 300 {
522			t.Fatalf("legacy conflict err = %v", err)
523		}
524	
525		// 重开后：null 来源（旧帧）与校正记录都保持。
526		if err := m2.Close(); err != nil {
