528		}
529		m3, err := Open(path)
530		if err != nil {
531			t.Fatal(err)
532		}
533		defer m3.Close()
534		if _, err := m3.Correct(Correction{ID: "x", Anchor: 100, Target: CorrectionTarget{X: 1}}); err == nil {
535			t.Fatal("old range became correctable after reopen")
536		}
537		recs, _ := m3.Corrections()
538		if len(recs) != 1 || recs[0].ID != "c2" {
539			t.Fatalf("records after legacy reopen = %v", recs)
540		}
541	}
