package posemap

import (
	"encoding/binary"
	"errors"
	"hash/crc32"
	"math"
	"os"
	"path/filepath"
	"testing"
)

func approxEq(t *testing.T, name string, got, want float64) {
	t.Helper()
	if math.IsNaN(want) {
		if !math.IsNaN(got) {
			t.Fatalf("%s = %v, want NaN", name, got)
		}
		return
	}
	if math.Abs(got-want) > 1e-10 {
		t.Fatalf("%s = %v, want %v", name, got, want)
	}
}

func baseConfig() Config {
	return Config{
